library(creditratingsystem)
for(name in c('.hy_horizon_end'))if(!exists(name))assign(name,getFromNamespace(name,'creditratingsystem'))
T<-list(event='default',horizon=30,time_unit='days',probability_measure='PHYSICAL',conditioning='performing');M<-list(target=T,training=list(data_fingerprint='synthetic-forward-oof',split_id='development',known_at='2021-01-01',data_origin='SYNTHETIC'),model_id='stack',model_version='1')
rows<-lapply(0:13,function(i)list(row_id=paste0('r',i),entity_id=paste0('e',i),group_id=paste0('g',i),role=if(i<12)'development'else'test',as_of=if(i<4)'2020-01-01'else if(i<12)'2020-03-01'else'2021-06-01',label_known_at=if(i<4)'2020-02-01'else if(i<12)'2020-04-01'else NULL,complete_through=if(i<4)'2020-01-31'else if(i<12)'2020-03-31'else NULL,prediction_known_at=if(i>=4&&i<12)'2020-03-01'else NULL))
train<-as.list(paste0('r',0:3));validation<-as.list(paste0('r',4:11));lineage<-setNames(lapply(c('scorecard','structural'),function(b)list(model_id=b,model_version='fold1',training_fingerprint='synthetic-base-train',reference='frozen fold fit manifest',target=T,prediction_origin='HELD_OUT',fit_row_ids=train,preprocessing_row_ids=train,selection_row_ids=list(),known_at='2020-02-15')),c('scorecard','structural'));plan<-list(horizon_date_rule='calendar_clamp',rows=rows,folds=list(list(fold_id='forward1',train_row_ids=train,validation_row_ids=validation,fit_known_at='2020-02-15',base_lineage=lineage)))
x<-rbind(matrix(NA_real_,4,2),cbind(c(.1,.2,.25,.35,.5,.6,.7,.9),c(.4,.3,.5,.4,.7,.65,.8,.75)),matrix(NA_real_,2,2));y<-as.list(c(0,0,1,1,0,1,0,0,1,0,1,1,NA,NA));spec<-list(input_scale='probability',penalty='ridge',lambda_path=.1,selected_lambda=.1,fit_intercept=TRUE,scale=TRUE,tolerance=1e-10)
fit<-function(x,y,plan,spec)do.call(fit_stacked_pd,c(list(x,y,base_model_ids=c('scorecard','structural'),split_plan=plan,meta_model_spec=spec),M));close<-function(a,b,tol=1e-8)stopifnot(max(abs(unlist(a)-unlist(b)))<tol);reject<-function(expr,code){e<-tryCatch(force(expr),error=identity);stopifnot(inherits(e,'error'),grepl(code,e$code,fixed=TRUE))}
for(scale in c('linear','log_odds','mixture')) {
 signals<-list(list(signal_id='score',model_id='score',model_version='1',row_ids=list('a','b'),pd=list(.1,.8),target=T,as_of='2024-01-01',known_at='2024-01-01'),list(signal_id='structure',model_id='structure',model_version='1',row_ids=list('a','b'),pd=list(.4,.2),target=T,as_of='2024-01-01',known_at='2024-01-01'))
 interpretation<-c(linear='estimator_pool',log_odds='log_odds_pool',mixture='latent_regime_mixture');contract<-list(interpretation=unname(interpretation[scale]),reference='explicit pooling exercise');w<-c(1,3);if(scale=='mixture'){contract$regime_ids<-list('score','structure');contract$conditional_regime_probabilities<-TRUE;w<-rbind(c(1,3),c(3,1))}
 result<-combine_pd_signals(signals,w,scale,contract)$value;expected<-if(scale=='linear')c(.325,.35)else if(scale=='mixture')c(.325,.65)else plogis(.25*qlogis(c(.1,.8))+.75*qlogis(c(.4,.2)));close(result$pd,expected);if(scale=='mixture')close(unlist(result$mixture_within_regime_variance)+unlist(result$mixture_between_regime_variance),expected*(1-expected))
 if(scale=='log_odds'){signals[[1]]$pd<-list(0,1);close(combine_pd_signals(signals,w,scale,contract)$value$pd,c(0,1));signals[[2]]$pd<-list(1,.2);reject(combine_pd_signals(signals,w,scale,contract),'BOUNDARY_CONFLICT')}
}
model<-fit(x,y,plan,spec);new<-rbind(c(.2,.3),c(.8,.7));actual<-predict_pd(model,new,feature_order=c('scorecard','structural'),expected_target=T)$value;direct<-do.call(fit_penalized_glm,c(list(x[5:12,],unlist(y[5:12]),feature_order=c('scorecard','structural')),spec[setdiff(names(spec),'input_scale')],M));close(actual,predict_pd(direct,new,feature_order=c('scorecard','structural'),expected_target=T)$value,1e-12)
changed_y<-y;changed_y[13:14]<-list('unobserved hypothetical label',1);changed_x<-x;changed_x[13:14,]<-rbind(c(-9,9),c(9,-9));changed<-fit(changed_x,changed_y,plan,spec);stopifnot(identical(changed$model$parameters,model$model$parameters),identical(changed$diagnostics$meta_data_fingerprint,model$diagnostics$meta_data_fingerprint))
constant_x<-x;constant_x[5:12,]<-matrix(rep(c(.2,.3),each=8),8,2);constant_y<-y;constant_y[5:12]<-as.list(c(0,0,0,0,0,0,1,1));constant<-fit(constant_x,constant_y,plan,spec);pred<-predict_pd(constant,rbind(c(.2,.3),c(.5,.3)),feature_order=c('scorecard','structural'),expected_target=T);close(pred$value,c(.25,.25),1e-7);stopifnot(pred$diagnostics$constant_base_departure_rows==1L)
bad<-plan;bad$folds[[1]]$base_lineage$scorecard$preprocessing_row_ids<-c(train,list('r4'));reject(fit(x,y,bad,spec),'LEAKAGE');bad<-plan;bad$rows[[5]]$group_id<-'g0';reject(fit(x,y,bad,spec),'LEAKAGE');bad<-plan;bad$rows[[5]]$complete_through<-'2020-03-15';reject(fit(x,y,bad,spec),'MATURITY');bad<-plan;bad$rows[[5]]$prediction_known_at<-'2020-03-02';reject(fit(x,y,bad,spec),'LEAKAGE');target<-T;target$horizon<-1;target$time_unit<-'months';stopifnot(as.character(.hy_horizon_end('2024-01-31',target))=='2024-02-29')
# Public dispatch retains common context and offset checks.
stopifnot(inherits(tryCatch(predict_pd(model,new,feature_order=c('scorecard','structural'),expected_target=T,offset=c(0,0)),error=identity),'error'))
stopifnot(inherits(tryCatch(predict_pd(model,new,feature_order=c('scorecard','structural'),expected_target=T,context=build_calculation_context(horizon=2,time_unit='years')),error=identity),'error'))
for(scale in c('linear','log_odds','mixture')){
 signals<-lapply(c('first','second'),function(s)list(signal_id=s,model_id=s,model_version='1',row_ids=list('a','b'),pd=list(.1,.8),target=T,as_of='2024-01-01',known_at='2024-01-01'));contract<-list(interpretation=unname(c(linear='estimator_pool',log_odds='log_odds_pool',mixture='latent_regime_mixture')[scale]),reference='hand invariants');if(scale=='mixture'){contract$regime_ids<-list('first','second');contract$conditional_regime_probabilities<-TRUE};w<-if(scale=='mixture')rbind(c(1,3),c(3,1))else c(1,3);close(combine_pd_signals(signals,w,scale,contract)$value$pd,c(.1,.8));signals[[2]]$pd<-list(.9,.2);w<-if(scale=='mixture')rbind(c(1,0),c(1,0))else c(1,0);close(combine_pd_signals(signals,w,scale,contract)$value$pd,c(.1,.8));w<-if(scale=='mixture')rbind(c(-1,2),c(1,1))else c(-1,2);reject(combine_pd_signals(signals,w,scale,contract),'HYBRID_WEIGHT')
}
